@ExtendWith(MockitoExtension.class)
class TaskServiceTest {
  @Mock TaskRepository repo;
  @InjectMocks TaskService service;

  @Test
  void listTasksForUser_noStatus_callsFindByUserIdOrderByCreatedAtDesc() {
    String userId = "user1";
    List<Task> expected = List.of(new Task(...));
    when(repo.findByUserIdOrderByCreatedAtDesc(userId)).thenReturn(expected);

    List<Task> result = service.listTasksForUser(userId);

    assertEquals(expected, result);
    verify(repo).findByUserIdOrderByCreatedAtDesc(userId);
  }

  @Test
  void listTasksForUser_overloadNullStatus_callsFindByUserIdOrderByCreatedAtDesc() {
    String userId = "user1";
    List<Task> expected = List.of(new Task(...));
    when(repo.findByUserIdOrderByCreatedAtDesc(userId)).thenReturn(expected);

    List<Task> result = service.listTasksForUser(userId, null);

    assertEquals(expected, result);
    verify(repo).findByUserIdOrderByCreatedAtDesc(userId);
  }

  @Test
  void listTasksForUser_withValidStatus_parsesAndCallsFindByUserIdAndStatus() {
    String userId = "user1";
    String status = "OPEN";
    TaskStatus parsed = TaskStatus.OPEN;
    List<Task> expected = List.of(new Task(...));
    when(repo.findByUserIdAndStatusOrderByCreatedAtDesc(userId, parsed)).thenReturn(expected);

    List<Task> result = service.listTasksForUser(userId, status);

    assertEquals(expected, result);
    verify(repo).findByUserIdAndStatusOrderByCreatedAtDesc(userId, parsed);
    verify(repo, never()).findByUserIdOrderByCreatedAtDesc(any());
  }

  @Test
  void listTasksForUser_withInvalidStatus_returnsEmptyListAndDoesNotCallRepo() {
    String userId = "user1";
    List<Task> result = service.listTasksForUser(userId, "NO_SUCH_STATUS");

    assertTrue(result.isEmpty());
    verify(repo, never()).findByUserIdOrderByCreatedAtDesc(any());
    verify(repo, never()).findByUserIdAndStatusOrderByCreatedAtDesc(any(), any());
  }
}
